package myPack;

public class Assesment34 {

	//WAP on continue keyword
	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		for(int i=0; i<=10; i++) {
			
			if(i%2==0) {
				System.out.println(i);
				
			}
			else {
				
				System.out.println("Skip : " +i);
				continue;
			
			}
		}

	}

}
